import pytest
from backend.app.schemas.document import ExtractedPage
from backend.app.services.chunking_service import ChunkingService, TextChunk

def test_chunk_page_preserves_page_number():
    chunker = ChunkingService(chunk_size=150, chunk_overlap=30)
    page_text = (
        "EvidenceAI is designed to eliminate ungrounded hallucinations in LLM answers. "
        "It achieves this by indexing research papers at the page level. "
        "Every claim generated by the system is mapped back to its supporting source sentence. "
        "This allows users to inspect exactly where every fact originates."
    )
    page = ExtractedPage(page_number=3, text=page_text, char_count=len(page_text), is_empty=False)

    chunks = chunker.chunk_page(page, document_id="doc_test_123")
    assert len(chunks) >= 2

    for c in chunks:
        assert c.page_number == 3
        assert c.document_id == "doc_test_123"
        assert c.chunk_id.startswith("doc_test_123_p3_")
        assert len(c.content) > 0
        assert c.token_count > 0
        assert c.start_char >= 0
        assert c.end_char > c.start_char

def test_chunking_overlap_constraint():
    with pytest.raises(ValueError) as exc_info:
        ChunkingService(chunk_size=200, chunk_overlap=200)
    assert "strictly smaller than chunk size" in str(exc_info.value)

def test_chunk_document_multi_page():
    chunker = ChunkingService(chunk_size=200, chunk_overlap=40)
    pages = [
        ExtractedPage(page_number=1, text="Page one introduction to machine learning principles.", char_count=52),
        ExtractedPage(page_number=2, text="Page two methodology with deep neural networks and attention mechanisms.", char_count=74)
    ]
    chunks = chunker.chunk_document(pages, document_id="doc_multi")

    assert len(chunks) == 2
    assert chunks[0].page_number == 1
    assert chunks[1].page_number == 2
    assert chunks[0].chunk_index == 0
    assert chunks[1].chunk_index == 1
